/* src/styles/6-components/scene.css */
/**
 * Scene — 장면형 첫 화면 (블록 카탈로그 scene · design-intelligence §6-1 H5)
 *   화면 전체를 쓰는 장면(기본은 사진) 위에 큰 표제를 올리고, 바닥에 바로가기 줄(quick-row)과 능선 전환(ridge),
 *   오른쪽에 뜬 패널(float-panel)을 둔다. 정본: src/blocks/scene/. MCP get_block("scene")
 *   <section class="section section--intro scene" aria-labelledby="scene-title">
 *     <img class="scene__photo" src="…" alt="">                          기본 배경(사진)
 *     <canvas class="scene__canvas" aria-hidden="true"></canvas>          프로젝트가 직접 그리는 선택 향상
 *     <div class="scene__veil" aria-hidden="true"></div>                  글자 자리를 어둡게 하는 장막
 *     <svg class="ridge" …>…</svg>
 *     <div class="container scene__body">
 *       <h1 class="scene__title" id="scene-title"><span class="scene__title-line">…</span> <span class="scene__title-line">…</span></h1>
 *       <p class="scene__lead">…</p>
 *       <nav class="quick-row">…</nav>
 *       <div class="float-panel">…</div>
 *     </div>
 *   </section>
 *   캔버스 약속: 프로젝트 스크립트가 첫 장면을 그린 뒤 section에 data-scene="ready"를 붙이면 캔버스가 드러난다.
 *     움직임 줄이기 설정이거나 그리기에 실패하면 아무것도 붙이지 않는다 — 사진이 남는다.
 *   --ridge-h: 바닥 능선 띠 높이. 본문 바닥 여백과 뜬 패널 위치를 이 값으로 계산한다.
 *   --quick-h: 바로가기 줄 한 줄 높이(1280px 이상에서 한 줄, 1024~1279px에서 두 줄).
 *   블록 예외(contracts/block-exceptions.json): 표제 행간 1.12, 0.9초 들어오기 움직임.
 * 레이어 밖에 둔다 — section.css(5-objects)·카탈로그 부품보다 뒤에서 조정한다.
 */
.scene {
  --ridge-h: clamp(4.8rem, 7vw, 10rem);
  --quick-h: 8rem;

  /* 바탕색은 사진도 캔버스도 없을 때만 보인다 */
  @apply relative overflow-hidden p-0 min-h-[100svh] bg-[var(--color-primary-40)] laptop:p-0;
}

.scene__photo {
  @apply absolute inset-0 w-full h-full max-w-none object-cover [object-position:50%_35%];
}

.scene__canvas {
  @apply absolute inset-0 block w-full h-full opacity-0 [transition:opacity_0.5s_ease];
}

.scene[data-scene="ready"] .scene__canvas {
  @apply opacity-100;
}

/* 위(머리글 자리)와 아래(표제·바로가기 자리)만 어둡게 하는 스크림 — 검정 알파 토큰만 쓴다 */
.scene__veil {
  @apply absolute inset-0 pointer-events-none;

  background: linear-gradient(180deg, var(--color-alpha-black-50) 0%, transparent 18%, transparent 55%, var(--color-alpha-black-75) 100%);
}

/* 좁은 화면에서는 표제·바로가기가 사진의 밝은 곳 위에 놓인다 — 사진 전체를 한 겹 더 어둡게 한다.
   1024px 이상은 글자가 아래 스크림 위에 있어 필요 없다 */
.scene__veil::before {
  @apply content-[''] absolute inset-0 [transition:opacity_0.4s_ease] laptop:hidden;

  background-color: color-mix(in srgb, var(--color-gray-100) 45%, transparent);
}

/* 캔버스 장면이 뜨면 옅게만 남긴다 — 장면의 밝은 색을 살린다 */
.scene[data-scene="ready"] .scene__veil::before {
  @apply opacity-40;
}

.scene__body {
  @apply relative pt-[10rem] pb-[calc(var(--ridge-h)+2.4rem)] text-[var(--color-gray-0)] laptop:flex laptop:flex-col laptop:justify-end laptop:h-[100svh] laptop:min-h-[80rem] laptop:pt-0 laptop:pb-[calc(var(--ridge-h)+1.6rem)];
}

/* KRDS 기준 밖(운영자 승인 대기): 표제 크기 4.4~12rem(display-large 6rem 상한)·행간 1.12(150% 기준) */
.scene__title {
  @apply m-0 [font-family:var(--font-heading)] font-semibold tracking-normal [word-break:keep-all] laptop:max-w-[56%];

  font-size: clamp(4.4rem, 7.6vw, 12rem);
  line-height: 1.12;
  text-shadow: 0 0.2rem 2.4rem var(--color-alpha-black-50);
}

.scene__title-line {
  @apply block;
}

.scene__lead {
  @apply m-0 mt-[2rem] max-w-[46rem] leading-[1.7] text-[var(--color-primary-5)] [word-break:keep-all] laptop:max-w-[56%];

  font-size: clamp(1.7rem, 1.4vw, 2rem);
}

/* 첫 화면 들어오기 — 표제 줄 → 소개 → 바로가기 → 패널 순으로 한 번 올라온다 */
@keyframes scene-rise {
  from {
    opacity: 0;
    transform: translateY(3.2rem);
  }

  to {
    opacity: 1;
    transform: none;
  }
}

@media (prefers-reduced-motion: no-preference) {
  .scene__title-line,
  .scene__lead,
  .scene .quick-row,
  .scene .float-panel {
    animation: scene-rise 0.9s cubic-bezier(0.2, 0.8, 0.2, 1) 0.2s backwards;
  }

  .scene__title-line:nth-child(2) { animation-delay: 0.31s; }
  .scene__lead { animation-delay: 0.42s; }
  .scene .quick-row { animation-delay: 0.53s; }
  .scene .float-panel { animation-delay: 0.64s; }
}

/* src/styles/6-components/scene-header.css */
/**
 * Scene Header — 장면 위 투명 머리글 (블록 카탈로그 scene의 부품)
 *   <header id="header" class="site-header scene-header">…카탈로그 헤더 마크업 그대로…</header>
 *   카탈로그 부품을 덮어쓰지 않고, 머리글 안에서 의미 토큰이 가리키는 값을 흰색 계열로 바꾼다.
 *   src/js/scene-header.js가 첫 화면을 벗어나면 data-scrolled를 붙여 짙은 바탕을 입힌다.
 *   로고는 흰색 파일을 쓴다(색을 필터로 뒤집지 않는다).
 *   블록 예외(contracts/block-exceptions.json): 통합검색 알약 반경.
 *   KRDS 헤더는 sticky + 밝은 바탕이 기본이다. 이 변형은 scene 블록과 함께일 때만 쓴다.
 * 레이어 밖에 둔다 — header.css(components 레이어)보다 뒤에서 조정한다.
 */
.scene-header {
  --color-text: var(--color-gray-0);
  --color-primary: var(--color-primary-20);
  --color-border-control: color-mix(in srgb, var(--color-gray-0) 50%, transparent);
  --color-button-text-fill-hover: color-mix(in srgb, var(--color-gray-0) 16%, transparent);
  --color-button-text-fill-pressed: color-mix(in srgb, var(--color-gray-0) 24%, transparent);

  @apply fixed inset-x-0 top-0 border-b-0 bg-transparent text-[var(--color-text)] [transition:background-color_0.3s_ease,box-shadow_0.3s_ease];
}

.scene-header[data-scrolled] {
  background-color: color-mix(in srgb, var(--color-primary-90) 92%, transparent);
  box-shadow: 0 0.1rem 0 color-mix(in srgb, var(--color-gray-0) 8%, transparent);
}

.scene-header .site-header__brand,
.scene-header .site-header__menu a,
.scene-header .site-header__search-link,
.scene-header .site-header__toggle {
  @apply text-[var(--color-text)];
}

/* 통합검색 — 흰 선 알약 안에 입력창과 글자 버튼 */
.scene-header .site-header__search {
  @apply gap-0 ps-[1.6rem] border border-[var(--color-border-control)] rounded-[99rem];
}

.scene-header .site-header__search-input {
  @apply w-[18rem] px-0 border-0 bg-transparent text-[1.5rem] text-[var(--color-text)];
}

.scene-header .site-header__search-input::placeholder {
  color: color-mix(in srgb, var(--color-gray-0) 75%, transparent);
}

.scene-header .site-header__search .btn {
  @apply border-transparent bg-transparent rounded-[99rem] text-[1.5rem] text-[var(--color-text)];
}

.scene-header .site-header__actions .btn--text {
  @apply text-[var(--color-text)];
}

/* 펼친 하위 메뉴는 흰 판이다 — 그 안에서는 토큰을 밝은 면 값으로 되돌린다 */
.scene-header .main-menu__submenu {
  --color-text: var(--color-gray-90);
  --color-primary: var(--color-primary-50);
}

/* src/styles/6-components/float-panel.css */
/**
 * Float Panel — 장면 위에 뜬 패널 (블록 카탈로그 scene의 부품)
 *   주요 항목을 넘겨 보는 흰 판. 안에 카탈로그 carousel을 그대로 넣는다(분수형 식별자만, 점 식별자 없음).
 *   <div class="float-panel">
 *     <h2 class="float-panel__title" id="scene-panel-title">주요사업</h2>
 *     <div class="carousel" role="region" aria-roledescription="carousel" aria-labelledby="scene-panel-title" data-carousel data-carousel-autoplay="7000">
 *       …carousel__controls · carousel__viewport · carousel__track…
 *       <div class="carousel__slide" …>
 *         <img class="float-panel__img" src="…" alt="…"> <h3 class="float-panel__name">…</h3>
 *         <ul class="float-panel__work" role="list"><li class="float-panel__task">…</li></ul>
 *       </div>
 *     </div>
 *     <a class="float-panel__more" href="…">사업영역 자세히 보기</a>
 *   </div>
 *   1024px 이상에서는 .scene__body의 오른쪽, 바로가기 줄 위에 뜬다. 미만에서는 바로가기 줄 아래에 놓인다.
 *   동작(자동 넘김·정지·초점 진입 시 정지)은 src/js/carousel.js 그대로다.
 *   블록 예외(contracts/block-exceptions.json): 그림자 blur 3.2rem, 이름 행간 1.3.
 * 레이어 밖에 둔다 — carousel.css(components 레이어)보다 뒤에서 조정한다.
 */
.float-panel {
  @apply relative z-[2] mt-[3.2rem] pt-[2rem] px-[2.4rem] pb-[2.4rem] rounded-[1.2rem] bg-[var(--color-surface)] text-[var(--color-text)] laptop:absolute laptop:right-[2.4rem] laptop:bottom-[calc(var(--ridge-h)+1.6rem+4rem+var(--quick-h)*2+2.4rem)] laptop:w-[34rem] laptop:mt-0 pc:w-[40rem] pc:bottom-[calc(var(--ridge-h)+1.6rem+4rem+var(--quick-h)+2.4rem)];

  box-shadow: 0 1.6rem 3.2rem -1.6rem var(--color-alpha-black-50);
}

/* 제목은 캐러셀 컨트롤과 같은 줄 왼쪽에 놓는다(컨트롤 높이 4.4rem에 맞춘 한 줄) */
.float-panel__title {
  @apply absolute left-[2.4rem] top-[2rem] m-0 text-[1.9rem] font-bold leading-[4.4rem] tracking-normal whitespace-nowrap;
}

.float-panel .carousel__controls {
  @apply gap-[0.4rem] mb-[1.6rem];
}

.float-panel .carousel__toggle,
.float-panel .carousel__nav {
  @apply border-[var(--color-border-light)] rounded-[0.8rem] [transition:background-color_0.2s_ease,border-color_0.2s_ease];
}

.float-panel .carousel__toggle:hover,
.float-panel .carousel__nav:hover {
  @apply bg-[var(--color-primary-5)] border-[var(--color-primary-50)];
}

/* 분수형 식별자를 모든 폭에서 쓴다(패널이 좁아 점 식별자를 두지 않는다) */
.float-panel .carousel__counter {
  @apply min-w-[5.2rem] laptop:block;
}

.float-panel__now {
  @apply font-bold text-[var(--color-text)];
}

.float-panel .carousel__viewport {
  @apply rounded-none;
}

.float-panel__img {
  @apply block w-full h-auto mb-[1.6rem] rounded-[0.8rem] object-cover [aspect-ratio:16/9] laptop:[aspect-ratio:21/9] pc:[aspect-ratio:2/1];
}

/* KRDS 기준 밖(운영자 승인 대기): 제목 행간 1.3(150% 기준) */
.float-panel__name {
  @apply m-0 mb-[1rem] [font-family:var(--font-heading)] text-[2.8rem] font-semibold leading-[1.3] tracking-normal [word-break:keep-all] laptop:text-[2.4rem] pc:text-[2.8rem];
}

.float-panel__work {
  @apply list-none m-0 p-0;
}

.float-panel__task {
  @apply relative ps-[1.6rem] text-[1.6rem] leading-[1.7] text-[var(--color-text-subtle)] [word-break:keep-all];
}

.float-panel__task::before {
  @apply content-[''] absolute left-0 top-[0.78em] w-[0.6rem] h-[0.6rem] rounded-full bg-[var(--color-point-30)];
}

.float-panel__more {
  @apply inline-flex items-center min-h-[4.4rem] mt-[1.2rem] font-bold text-[var(--color-text-primary)] [text-underline-offset:0.35em];
}

.float-panel__more:visited {
  @apply text-[var(--color-text-primary)];
}

/* 낮은 화면: 사진을 납작하게 해 머리글과 겹치지 않게 한다 */
@media (min-width: 1024px) and (max-height: 860px) {
  .float-panel__img {
    @apply [aspect-ratio:21/9];
  }

  .float-panel__name {
    @apply text-[2.4rem];
  }
}

/* src/styles/6-components/quick-row.css */
/**
 * Quick Row — 장면 바닥의 글자 바로가기 줄 (블록 카탈로그 scene의 부품 · design-intelligence §6-2 Q3)
 *   <nav class="quick-row" aria-label="자주 찾는 서비스">
 *     <ul class="quick-row__list" role="list">
 *       <li><a class="quick-row__link" href="…"><svg class="icon" …>…</svg>입찰·계약정보</a></li>
 *     </ul>
 *   </nav>
 *   짙은 면·장면 위에 놓는다(글자 흰색). 360px 2단 → 768px 3단 → 1280px 6단 한 줄.
 *   아이콘은 배경 없이 글자 왼쪽에 둔다.
 * 레이어 밖에 둔다 — scene과 같은 층.
 */

/* 좁은 화면에서는 짙은 판에 담는다 — 글자가 장면 속 밝은 곳과 겹치면 읽히지 않는다 */
.quick-row {
  @apply mt-[4rem] border-t max-laptop:mt-[3.2rem] max-laptop:px-[1.6rem] max-laptop:border-t-0 max-laptop:rounded-[1.2rem] max-laptop:bg-[var(--color-primary-90)];

  border-color: color-mix(in srgb, var(--color-gray-0) 35%, transparent);
}

.quick-row__list {
  /* 두 줄로 꺾이는 항목이 있어도 줄 높이가 어긋나지 않게 모든 줄을 같은 높이로 둔다 */
  @apply grid grid-cols-2 [grid-auto-rows:1fr] list-none m-0 p-0 tablet:grid-cols-3 pc:grid-cols-6;
}

.quick-row__link {
  @apply flex items-center gap-[1rem] h-full min-h-[6.4rem] px-[0.4rem] py-[1.2rem] border-b text-[1.6rem] font-bold leading-[1.5] text-[var(--color-gray-0)] no-underline [word-break:keep-all] [transition:color_0.2s_ease] pc:min-h-[8rem] pc:ps-0 pc:pe-[1.2rem] pc:pt-[1.6rem] pc:pb-0 pc:border-b-0;

  border-color: color-mix(in srgb, var(--color-gray-0) 18%, transparent);
}

.quick-row__link:visited {
  @apply text-[var(--color-gray-0)];
}

.quick-row__link:hover {
  @apply text-[var(--color-primary-20)];
}

.quick-row__link .icon {
  @apply text-[var(--color-primary-20)];
}

/* src/styles/6-components/ridge.css */
/**
 * Ridge — 능선 전환 (블록 카탈로그 scene·logo-row의 부품)
 *   윗면의 바닥에 놓고 아랫면의 색으로 칠하는 각진 실루엣. 면과 면 사이를 직선 대신 대상의 윤곽으로 넘긴다.
 *   <svg class="ridge" viewBox="0 0 1440 100" preserveAspectRatio="none" aria-hidden="true" focusable="false">
 *     <path class="ridge__slope" d="…"/> <path class="ridge__slope-far" d="…"/> <path class="ridge__slope-near" d="…"/>
 *     <path class="ridge__ground" d="…"/>
 *   </svg>
 *   높이는 부모의 --ridge-h. 색은 --ridge-ground·--ridge-slope·--ridge-far·--ridge-near로 받는다.
 *   기본값은 짙은 면(primary-90) 색이다 — 아랫면이 다른 색이면 부모에서 네 값을 그 면의 토큰으로 바꾼다.
 *   모양은 프로젝트마다 대상의 지형·사물에서 온 선으로 바꾼다(블록 메타데이터의 변형 축 참고).
 *   블록 예외(contracts/block-exceptions.json): 인라인 svg(R-27) — 아이콘이 아니라 면 전환 그림이다.
 * 레이어 밖에 둔다 — scene과 같은 층.
 */
.ridge {
  @apply absolute inset-x-0 bottom-0 block w-full max-w-none h-[var(--ridge-h,8rem)] pointer-events-none;
}

.ridge__ground {
  fill: var(--ridge-ground, var(--color-primary-90));
}

.ridge__slope {
  fill: var(--ridge-slope, var(--color-primary-80));
}

.ridge__slope-far {
  fill: var(--ridge-far, color-mix(in srgb, var(--color-primary-80) 55%, var(--color-primary-70)));
}

.ridge__slope-near {
  fill: var(--ridge-near, color-mix(in srgb, var(--color-primary-90) 50%, var(--color-primary-80)));
}
